```javascript
function getMatchingEntries(obj) {
    const pattern = new RegExp(`\\b${arguments[0]}`, 'g');

    // Split the string into individual key parts
    const keys = arguments[0].split('.');

    for (let i = 1; i < arguments.length; i++) {
        let currentObj = obj;

        // Check each key part of the path
        for (const key of keys.slice(0, -1)) {
            if (!currentObj || !(key in currentObj)) {
                break;
            }

            currentObj = currentObj[key];
        }

        // If we reached the last key
        if (keys.length === 1 && !currentObj) {
            continue;
        } else if (!(keys[keys.length - 1] in currentObj)) {
            break;
        }

        currentObj = currentObj[keys[keys.length - 1]];
    }

    return currentObj;
}

