    public static void main(String[] args) {
        double CO2Emissions = calculateCarbonDioxideEmissions(100); // Assuming we burned 100 tons of coal
        System.out.println("The carbon dioxide emissions from burning fossil fuels would be " + CO2Emissions + " kg.");
    }

    public static double calculateCarbonDioxideEmissions(double tonsOfCoalBurned) {
        return tonsOfCoalBurned * 93; // Conversion factor: 1 ton of coal emits approximately 93 kg of CO2
    }
}
```
